/* the faces, loaded where they are DECLARED: ./theme.css names --font-display,
   --font-body and --font-gochi, and this file is what makes those names resolve
   to real glyphs. it lives here so no consumer has to load a face of its own —
   a consumer that imports the tokens and not the faces renders the whole product
   in the ua default with nothing failing anywhere, which is a hole no structural
   gate can close.

   the binaries in ./fonts are OUR subsets rather than a font package's, and the
   reason is one feature. quicksand draws an alternate zero with a dot in its
   bowl and exposes it as the opentype `zero` feature — which is what
   `font-variant-numeric: slashed-zero` (tailwind's `slashed-zero`) asks a font
   for, whatever the designer drew. a subsetter's default layout-feature retain
   list does not include `zero`, so an off-the-shelf build drops the feature and
   its glyph before the browser ever sees them, and the four call sites on the
   fee-comparison pages that ask for it get a plain zero and no error.
   see packages/brand/design-system.md → "The faces".

   regenerate with ./fonts/generate.sh, which re-derives the subsets from the
   upstream google/fonts sources. the unicode-ranges below are the standard
   google/fontsource ones verbatim; each subset is cut to the union of its range
   and the coverage the committed file already has, so a regeneration can never
   serve less than the site served before.

   `font-display: swap`: the type is the brand, and a flash of fallback beats a
   flash of nothing. */

/* quicksand — the display AND body face (two roles, one family; ./theme.css) */
@font-face {
  font-family: "Quicksand Variable";
  font-style: normal;
  font-display: swap;
  font-weight: 300 700;
  src: url(./fonts/quicksand-latin-wght-normal.woff2) format("woff2-variations");
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA,
    U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193,
    U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: "Quicksand Variable";
  font-style: normal;
  font-display: swap;
  font-weight: 300 700;
  src: url(./fonts/quicksand-latin-ext-wght-normal.woff2)
    format("woff2-variations");
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7,
    U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF,
    U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}

@font-face {
  font-family: "Quicksand Variable";
  font-style: normal;
  font-display: swap;
  font-weight: 300 700;
  src: url(./fonts/quicksand-vietnamese-wght-normal.woff2)
    format("woff2-variations");
  unicode-range:
    U+0102-0103, U+0110-0111, U+0128-0129, U+0168-0169,
    U+01A0-01A1, U+01AF-01B0, U+0300-0301, U+0303-0304, U+0308-0309, U+0323,
    U+0329, U+1EA0-1EF9, U+20AB;
}

/* gochi hand — the decorative aside. static, one weight, latin only.
   carried here for the same reason as quicksand: the token is declared in this
   package, so the face belongs in this package. it needs no feature quicksand
   needed — it is subset the same way purely so both faces have one pipeline. */
@font-face {
  font-family: "Gochi Hand";
  font-style: normal;
  font-display: swap;
  font-weight: 400;
  src: url(./fonts/gochi-hand-latin-400-normal.woff2) format("woff2");
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA,
    U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193,
    U+2212, U+2215, U+FEFF, U+FFFD;
}
